import { Progress } from "@/components/ui/pop-aria-progress";
export function PopProgress({
  label,
  value,
  description,
}: {
  label: string;
  value: number;
  description?: string;
}) {
  const percent = Math.min(
    100,
    Math.max(0, Number.isFinite(value) ? value : 0),
  );
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center justify-between gap-4 text-sm">
        <span className="font-medium">{label}</span>
        <span className="tabular-nums text-muted-foreground">
          {Math.round(percent)}%
        </span>
      </div>
      <Progress
        value={percent}
        aria-label={label}
        aria-valuenow={percent}
        aria-valuemin={0}
        aria-valuemax={100}
      />
      {description ? (
        <p className="text-xs text-muted-foreground">{description}</p>
      ) : null}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "cn";
import {
  Label as LabelPrimitive,
  ProgressBar as ProgressPrimitive,
  type LabelProps,
  type ProgressBarProps as ProgressPrimitiveProps,
} from "react-aria-components";

type ProgressContextValue = {
  percentage?: number;
  isIndeterminate: boolean;
  valueText?: string;
};

const ProgressContext = React.createContext<ProgressContextValue | null>(null);

function useProgress() {
  const context = React.useContext(ProgressContext);
  if (!context) {
    throw new Error("useProgress must be used within a Progress.");
  }

  return context;
}

function ProgressContent({
  children,
  percentage,
  isIndeterminate,
  valueText,
}: ProgressContextValue & {
  children?: React.ReactNode;
}) {
  const context = React.useMemo(
    () => ({ percentage, isIndeterminate, valueText }),
    [percentage, isIndeterminate, valueText],
  );

  return (
    <ProgressContext value={context}>
      {children}
      <ProgressTrack>
        <ProgressIndicator />
      </ProgressTrack>
    </ProgressContext>
  );
}

function Progress({
  className,
  children,
  ...props
}: Omit<ProgressPrimitiveProps, "children" | "className"> & {
  children?: React.ReactNode;
  className?: string;
}) {
  return (
    <ProgressPrimitive
      data-slot="progress"
      className={cn("flex flex-wrap gap-3", className)}
      {...props}
    >
      {({ percentage, valueText, isIndeterminate }) => (
        <ProgressContent
          percentage={percentage}
          valueText={valueText}
          isIndeterminate={isIndeterminate}
        >
          {children}
        </ProgressContent>
      )}
    </ProgressPrimitive>
  );
}

function ProgressTrack({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn(
        "relative flex h-1 w-full items-center overflow-x-hidden rounded-full bg-muted",
        className,
      )}
      data-slot="progress-track"
      {...props}
    />
  );
}

function ProgressIndicator({
  className,
  style,
  ...props
}: React.ComponentProps<"span">) {
  const { percentage, isIndeterminate } = useProgress();

  return (
    <span
      data-slot="progress-indicator"
      className={cn("h-full bg-primary transition-all", className)}
      style={{
        ...style,
        width: `${isIndeterminate ? 100 : (percentage ?? 0)}%`,
      }}
      {...props}
    />
  );
}

function ProgressLabel({ className, ...props }: LabelProps) {
  return (
    <LabelPrimitive
      className={cn("text-sm font-medium", className)}
      data-slot="progress-label"
      {...props}
    />
  );
}

function ProgressValue({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  children?: (value: string) => React.ReactNode;
}) {
  const { valueText } = useProgress();
  return (
    <span
      className={cn(
        "ml-auto text-sm text-muted-foreground tabular-nums",
        className,
      )}
      data-slot="progress-value"
      {...props}
    >
      {children && valueText != null ? children(valueText) : valueText}
    </span>
  );
}

export {
  Progress,
  ProgressTrack,
  ProgressIndicator,
  ProgressLabel,
  ProgressValue,
};

import {
  Avatar,
  AvatarImage,
  AvatarFallback,
} from "@/components/ui/pop-aria-avatar";
export function PopAvatarStack({
  people,
  max = 4,
}: {
  people: { name: string; image?: string }[];
  max?: number;
}) {
  const limit = Math.max(1, Math.floor(max));
  return (
    <div
      className="flex"
      aria-label={people.map((person) => person.name).join(", ")}
    >
      {people.slice(0, limit).map((person, index) => (
        <Avatar
          key={`${person.name}-${index}`}
          size="default"
          className="ring-2 ring-background -ml-1.5 first:ml-0"
        >
          {person.image ? (
            <AvatarImage src={person.image} alt={person.name} />
          ) : null}
          <AvatarFallback>
            {person.name
              .split(" ")
              .map((part) => part[0])
              .slice(0, 2)
              .join("")}
          </AvatarFallback>
        </Avatar>
      ))}
      {people.length > limit ? (
        <Avatar
          size="default"
          className="ring-2 ring-background -ml-1.5 first:ml-0"
        >
          <AvatarFallback>+{people.length - limit}</AvatarFallback>
        </Avatar>
      ) : null}
    </div>
  );
}

